const crypto=require('crypto');
const rows=$input.all().map(x=>x.json||{});
if(rows.length!==7)throw Error('QA_CENTRAL_REGISTRY_NOT_SEVEN_ROWS');
if(rows.some(r=>r.approval_scope!=='SYNTHETIC_ONLY'||r.owner_authority_verified!==false||r.read_only!==true))throw Error('REAL_STORE_AUTHORITY_NOT_ALLOWED');
const website=rows.filter(r=>r.channel==='website'&&r.installation_ref==='QA_WEB_WIDGET_A'&&r.status==='QA_APPROVED');
if(website.length!==1)throw Error('WEBSITE_BINDING_UNKNOWN_OR_DUPLICATED');
const b=website[0],origin='https://qa-shop-a.example.invalid';
if(b.tenant_ref!=='QA_TENANT_1'||b.store_ref!=='QA_STORE_A'||b.bot_ref!=='QA_BOT_A'||b.tool_allowlist!=='catalog_read'||b.subscription_active!==true||b.store_paused!==false)throw Error('QA_WEBSITE_BINDING_NOT_SAFE');
const key='QA_ONLY_V173_FAKE_PRIVATE_KEY_NEVER_PRODUCTION_123456789';
const kid='qa_v1';
const now=Math.floor(Date.now()/1000);
const sid=crypto.randomBytes(24).toString('base64url');
const base={v:1,iss:'t404-qa-issuer',aud:'t404-website-chat',iat:now,nbf:now,exp:now+300,sid,channel:'website',installation_ref:b.installation_ref,origin,
  tenant_ref:b.tenant_ref,store_ref:b.store_ref,bot_ref:b.bot_ref,bot_version:b.bot_version,prompt_version:b.prompt_version,
  knowledge_version:b.knowledge_version,policy_version:b.policy_version,scope:'QA_CATALOG_ONLY'};
const sign=(claims,k=kid)=>{
 const body=Buffer.from(JSON.stringify(claims),'utf8').toString('base64url');
 const partial='t404s1.'+k+'.'+body;
 return partial+'.'+crypto.createHmac('sha256',key).update(partial,'utf8').digest('base64url');
};
const token=sign(base);
function make(n,more={}){
 return {case_id:'QA_V173_'+String(n).padStart(2,'0'),expected:'ALLOW',token,origin,installation_ref:b.installation_ref,
  channel:'website',event_id:'QA_MSG_'+String(n).padStart(2,'0'),text:'QA_SKU_001',requested_tool:'catalog_read',...more};
}
const first=make(1),alterSig=token.slice(0,-1)+(token.endsWith('A')?'B':'A');
const cases=[
 first,
 make(2),make(3),
 {...first,case_id:'QA_V173_04',expected:'DUPLICATE'},
 {...first,case_id:'QA_V173_05',expected:'DENY',text:'QA_CONFLICT'},
 make(6,{expected:'DENY',token:alterSig}),
 make(7,{expected:'DENY',token:''}),
 make(8,{expected:'DENY',origin:'https://qa-shop-b.example.invalid'}),
 make(9,{expected:'DENY',installation_ref:'QA_WEB_WIDGET_B'}),
 make(10,{expected:'DENY',installation_ref:'QA_UNKNOWN_WIDGET'}),
 make(11,{expected:'DENY',channel:'messenger'}),
 make(12,{expected:'DENY',token:sign({...base,iat:now-601,nbf:now-601,exp:now-301})}),
 make(13,{expected:'DENY',token:sign({...base,iat:now+301,nbf:now+301,exp:now+601})}),
 make(14,{expected:'DENY',token:token.replace('qa_v1','wrong_kid')}),
 make(15,{expected:'DENY',token:sign({...base,aud:'wrong-audience'})}),
 make(16,{expected:'DENY',token:sign({...base,iss:'wrong-issuer'})}),
 make(17,{expected:'DENY',token:sign({...base,store_ref:'QA_STORE_B'})}),
 make(18,{expected:'DENY',token:sign({...base,bot_ref:'QA_BOT_B'})}),
 make(19,{expected:'DENY',token:sign({...base,prompt_version:'QA_PROMPT_B_V1'})}),
 make(20,{expected:'DENY',token:sign({...base,knowledge_version:'QA_KNOWLEDGE_B_V1'})}),
 make(21,{expected:'DENY',token:sign({...base,scope:'QA_ORDER_WRITE'})}),
 make(22,{expected:'DENY',token:'evil.none.signature'}),
 make(23,{expected:'DENY',requested_tool:'create_order'}),
 make(24,{expected:'DENY',requested_tool:'order_read'}),
 make(25,{expected:'DENY',requested_tool:'update_price'}),
 make(26,{expected:'DENY',event_id:''}),
 make(27,{expected:'DENY',text:''}),
 make(28,{expected:'DENY',text:'X'.repeat(501)}),
 make(29,{expected:'DENY',store_id:'QA_STORE_B'}),
 make(30,{expected:'DENY',tenant_id:'QA_TENANT_2'}),
 make(31,{expected:'DENY',bot_id:'QA_BOT_B'}),
 make(32,{expected:'DENY',verified:true}),
 make(33,{expected:'DENY',customer_identity_linked:true}),
 make(34,{expected:'DENY',message_type:'image'}),
 make(35,{expected:'DENY',token:sign({...base,exp:now+3600})}),
 make(36,{expected:'DENY',token:sign({...base,policy_version:'QA_POLICY_OTHER'})}),
 make(37,{expected:'DENY',origin:'http://qa-shop-a.example.invalid'}),
 make(38,{expected:'DENY',token:sign({...base,installation_ref:'QA_WEB_WIDGET_B'})})
];
return [{json:{contract:'T404_V173_N8N_WEB_SESSION_QA_V1',trust:'SYNTHETIC_SERVER_MINT_ONLY',created_by:'QA_CENTRAL_DATA_TABLE_BINDING',cases}}];

const crypto=require('crypto'),key='QA_ONLY_V173_FAKE_PRIVATE_KEY_NEVER_PRODUCTION_123456789';
const batch=$input.first()?.json||{},rows=$('Load V17.2 QA Store Bot Profiles').all().map(x=>x.json||{});
if(batch.contract!=='T404_V173_N8N_WEB_SESSION_QA_V1'||batch.trust!=='SYNTHETIC_SERVER_MINT_ONLY'||
 !Array.isArray(batch.cases)||batch.cases.length!==38||rows.length!==7)throw Error('V173_SESSION_QA_INPUT_INVALID');
if(rows.some(r=>r.approval_scope!=='SYNTHETIC_ONLY'||r.owner_authority_verified!==false||r.read_only!==true))throw Error('UNAUTHORIZED_REAL_BINDING_IN_QA');
const allowed=new Set(['case_id','expected','token','origin','installation_ref','channel','event_id','text','requested_tool']);
const safeEqual=(a,b)=>{const x=Buffer.from(a),y=Buffer.from(b);return x.length===y.length&&crypto.timingSafeEqual(x,y);};
const seen=new Map(),results=[];
for(const c of batch.cases){
 let status='DENY',reason='QA_DENIED',store=null,bot=null,price=null,stock=null,botVersion=null;
 try{
  if(Object.keys(c).some(x=>!allowed.has(x)))throw Error('UNTRUSTED_CLIENT_AUTHORITY_CLAIM');
  if(c.channel!=='website'||c.origin!=='https://qa-shop-a.example.invalid'||c.installation_ref!=='QA_WEB_WIDGET_A')throw Error('UNAUTHORIZED_WEBSITE_ORIGIN_INSTALLATION');
  if(typeof c.token!=='string'||c.token.length<150||c.token.length>2300)throw Error('TOKEN_LENGTH_DENIED');
  const p=c.token.split('.');
  if(p.length!==4||p[0]!=='t404s1'||p[1]!=='qa_v1'||!/^[A-Za-z0-9_-]+$/.test(p[2])||
   !/^[A-Za-z0-9_-]+$/.test(p[3]))throw Error('TOKEN_FORMAT_OR_KEY_DENIED');
  const actual=crypto.createHmac('sha256',key).update(p.slice(0,3).join('.')).digest('base64url');
  if(!safeEqual(actual,p[3]))throw Error('BAD_SIGNED_SESSION');
  let claims;try{claims=JSON.parse(Buffer.from(p[2],'base64url').toString('utf8'));}catch{throw Error('BAD_SESSION_PAYLOAD');}
  const now=Math.floor(Date.now()/1000);
  if(claims.v!==1||claims.iss!=='t404-qa-issuer'||claims.aud!=='t404-website-chat'||
  claims.channel!=='website'||claims.installation_ref!==c.installation_ref||claims.origin!==c.origin||
  claims.scope!=='QA_CATALOG_ONLY'||typeof claims.sid!=='string'||!/^[A-Za-z0-9_-]{32}$/.test(claims.sid)||
  !Number.isSafeInteger(claims.iat)||!Number.isSafeInteger(claims.nbf)||!Number.isSafeInteger(claims.exp)||
  claims.exp-claims.iat!==300||claims.nbf!==claims.iat||claims.iat>now+30||claims.nbf>now||claims.exp<=now)throw Error('SESSION_CLAIM_OR_TTL_DENIED');
  const candidates=rows.filter(r=>r.channel==='website'&&r.installation_ref===claims.installation_ref);
  if(candidates.length!==1)throw Error('SERVER_WEBSITE_BINDING_NOT_UNIQUE');
  const r=candidates[0];
  if(r.status!=='QA_APPROVED'||r.subscription_active!==true||r.store_paused!==false||
   r.tool_allowlist!=='catalog_read')throw Error('STORE_OR_BOT_PAUSED_REVOKED');
  for(const field of ['tenant_ref','store_ref','bot_ref','bot_version','prompt_version','knowledge_version','policy_version'])
   if(r[field]!==claims[field])throw Error('SESSION_BOT_STORE_PROFILE_CHANGED');
  if(c.requested_tool!=='catalog_read')throw Error('WRITE_OR_ORDER_READ_TOOL_DENIED');
  if(typeof c.event_id!=='string'||!/^QA_MSG_\d{2}$/.test(c.event_id)||
   typeof c.text!=='string'||c.text.length<1||c.text.length>500)throw Error('INVALID_EVENT_ID_OR_TEXT');
  const replayKey=claims.sid+'|'+c.event_id;
  const fingerprint=[c.token,c.channel,c.origin,c.installation_ref,c.event_id,c.text,c.requested_tool].join('|');
  if(seen.has(replayKey)){
   if(seen.get(replayKey)!==fingerprint)throw Error('CONFLICTING_QA_MESSAGE_REPLAY');
   status='DUPLICATE';reason='IN_MEMORY_QA_DUPLICATE_NO_ACTION';
  }else{
   seen.set(replayKey,fingerprint);
   status='ALLOW';reason='SERVER_MINTED_QA_SESSION_CATALOG_ONLY';
   store=r.store_ref;bot=r.bot_ref;price=r.price_vnd;stock=r.stock;botVersion=r.bot_version;
  }
 }catch(e){status='DENY';reason=String(e?.message||'DENIED').slice(0,70);}
 results.push({case_id:c.case_id,expected:c.expected,status,reason,store,bot,bot_version:botVersion,price_vnd:price,stock,
  customer_cross_channel_identity_verified:false,real_website_session_issued:false,hosted_store_rls_verified:false,
  provider_sends:0,model_calls:0,commerce_writes:0,outbound:'MOCK_ONLY_NOT_SENT'});
}
return [{json:{contract:batch.contract,source_mode:batch.trust,bindings:rows.length,results}}];

const x=$input.first()?.json||{},rows=x.results||[];
if(x.contract!=='T404_V173_N8N_WEB_SESSION_QA_V1'||x.source_mode!=='SYNTHETIC_SERVER_MINT_ONLY'||x.bindings!==7||
 rows.length!==38||new Set(rows.map(r=>r.case_id)).size!==38)throw Error('V173_WEBSITE_QA_CONTRACT_INVALID');
for(const r of rows){
 if(r.status!==r.expected)throw Error('P0_V173_CASE_FAILED_'+r.case_id+'_'+r.status+'_NEEDS_'+r.expected);
 if(r.provider_sends!==0||r.model_calls!==0||r.commerce_writes!==0||
 r.customer_cross_channel_identity_verified!==false||r.real_website_session_issued!==false||r.hosted_store_rls_verified!==false||
 r.outbound!=='MOCK_ONLY_NOT_SENT')throw Error('V173_UNAUTHORIZED_REAL_ACTION');
 if(r.status==='ALLOW'&&(r.store!=='QA_STORE_A'||r.bot!=='QA_BOT_A'||r.price_vnd!==159000||
 r.bot_version!=='QA_BOT_A_V1'))throw Error('V173_REAL_STORE_OR_BOT_SCOPE_WRONG');
 if(r.status==='DENY'&&(r.store!==null||r.bot!==null))throw Error('V173_DENIED_CONTEXT_EXPOSED');
}
const count=(status)=>rows.filter(r=>r.status===status).length;
if(count('ALLOW')!==3||count('DENY')!==34||count('DUPLICATE')!==1)throw Error('V173_QA_DISTRIBUTION_CHANGED');
return [{json:{status:'V173_WEBSITE_SESSION_TO_STORE_BOT_QA_PASS',total:rows.length,passed:rows.length,
 allow:count('ALLOW'),deny:count('DENY'),duplicate:count('DUPLICATE'),bindings:7,
 website_qa_session_hmac_verified:true,central_v172_bot_binding_read:true,
 same_session_three_distinct_messages:true,real_website_session_issued:false,
 hosted_store_rls_verified:false,customer_cross_channel_identity_verified:false,
 all_provider_sends:0,all_llm_calls:0,all_commerce_writes:0,
 reply:'MOCK_ONLY_NOT_SENT',cases:rows.map(r=>({id:r.case_id,status:r.status,reason:r.reason,
  store:r.store,bot:r.bot,price_vnd:r.price_vnd}))}}];
